import { useState, useEffect } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import styles from '@/styles/Footer.module.css';

const FOOTER_LINKS = [
  { label: '選ばれる理由', href: '/reason' },
  { label: 'コース・料金', href: '/course' },
  { label: '施設紹介', href: '/facility' },
  { label: '指導者紹介', href: '/coaches' },
  { label: 'お知らせ', href: '/news' },
  { label: 'コラム', href: '/column' },
  { label: 'アクセス', href: '/about' },
  { label: 'お問い合わせ', href: '/contact' },
];

export default function Footer() {
  const [partners, setPartners] = useState([]);

  useEffect(() => {
    const api = process.env.NEXT_PUBLIC_WP_API || 'http://ssba.e3.valueserver.jp/wp/wp-json/ssba/v1';
    fetch(`${api}/partners`)
      .then((r) => r.json())
      .then((d) => setPartners(d.partners || []))
      .catch(() => {});
  }, []);

  return (
    <footer className={styles.footer}>
      <div className={styles.footerInner}>
        <div className={styles.footerTop}>
          {/* 左側：会社情報 */}
          <div className={styles.footerInfo}>
            <div className={styles.footerLogo}>
              <Image
                src="/images/logo_before.png"
                alt="SSBA"
                width={120}
                height={43}
              />
            </div>
            <p className={styles.footerName}>SSBA野球塾</p>
            <p className={styles.footerSubName}>Shootingstar baseball academy</p>
            <address className={styles.footerAddress}>
              <p>福岡県久留米市安武町安武本2930-6</p>
              <p>TEL：<a href="tel:09013627517">090-1362-7517</a></p>
              <p>Mail：<a href="mailto:ssba1223dn@gmail.com">ssba1223dn@gmail.com</a></p>
            </address>
            <div className={styles.footerLinks}>
              <Link href="/privacy" className={styles.footerLink}>プライバシーポリシー</Link>
              <span className={styles.footerLinkSeparator}>|</span>
              <Link href="/admin/availability" className={styles.footerLink}>管理画面</Link>
            </div>
          </div>

          {/* 右側：関連団体 + 関連事業 */}
          <div className={styles.footerRight}>
            {/* 関連団体 */}
            {partners.length > 0 && (
              <div className={styles.footerPartners}>
                <h4 className={styles.footerSectionTitle}>関連団体</h4>
                <div className={styles.footerPartnersGrid}>
                  {partners.slice(0, 4).map((partner) => (
                    <a
                      key={partner.id}
                      href={partner.href || '#'}
                      className={styles.footerPartnerItem}
                      target={partner.href && partner.href !== '#' ? '_blank' : undefined}
                      rel={partner.href && partner.href !== '#' ? 'noopener noreferrer' : undefined}
                    >
                      <img
                        src={partner.src}
                        alt={partner.alt}
                        onError={(e) => { e.target.style.display = 'none'; }}
                      />
                    </a>
                  ))}
                </div>
              </div>
            )}

            {/* フッターナビゲーション */}
            <div className={styles.footerBusiness}>
              <div className={styles.footerBusinessGrid}>
                {FOOTER_LINKS.map((link) => (
                  <Link key={link.label} href={link.href} className={styles.footerBusinessLink}>
                    {link.label}
                  </Link>
                ))}
              </div>
            </div>
          </div>
        </div>

        <div className={styles.footerBottom}>
          <p className={styles.copyright}>
            &copy; {new Date().getFullYear()} SSBA - Shootingstar Baseball Academy. All rights reserved.
          </p>
        </div>
      </div>
    </footer>
  );
}
